export function splitNovelChapters(text){const starts=[...text.matchAll(/^第[零一二三四五六七八九十百千0-9]+章[^\n]*/gm)];if(!starts.length)return [{title:'原文',text,start:0,end:text.length}];return starts.map((match,index)=>{const start=index?match.index:0,end=starts[index+1]?.index??text.length;return {title:match[0].trim(),text:text.slice(start,end),start,end};});}
export function computeSubtitleMatches(videos=[],subtitles=[]){
  const stem=name=>String(name||'').replace(/\\/g,'/').split('/').pop().replace(/\.[^.]+$/,'').toLowerCase();
  const edges=new Map(subtitles.map(sub=>[sub.filename,videos.filter(v=>{const sv=stem(v.name),ss=stem(sub.filename);return sv&&(ss===sv||['.','-','_'].some(sep=>ss.startsWith(sv+sep)));}).map(v=>v.media_id)]));
  const counts=new Map(videos.map(v=>[v.media_id,[...edges.values()].filter(ids=>ids.includes(v.media_id)).length]));
  return subtitles.map(sub=>{const ids=edges.get(sub.filename)||[];return {subtitle_name:sub.filename,video_ids:ids,status:ids.length===1&&counts.get(ids[0])===1?'matched':ids.length?'conflict':'unmatched'};});
}
export function computeTranslationLengthWarning(sourceLanguage,sourceText){
  const text=String(sourceText||''),lang=String(sourceLanguage||'').trim().toLowerCase(),len=text.length;
  if(['中文（简体）','中文','zh','zh-cn'].includes(lang)&&len>4500)return {exceeded:true,limit:4500,actual:len,message:`当前原文 ${len} 字，超过中文单集建议上限 4,500 字，建议按集拆分后再翻译。`};
  if(['英语','英文','english','en','en-us'].includes(lang)&&len>64000)return {exceeded:true,limit:64000,actual:len,message:`当前原文 ${len} 字符，超过英文单集建议上限 64,000 字符，建议按集拆分后再翻译。`};
  return {exceeded:false,limit:['英语','英文','english','en','en-us'].includes(lang)?64000:4500,actual:len,message:`当前原文 ${len} 字符（建议单集上限：中文 4,500 字 / 英文 64,000 字符）`};
}
