    const n=++epoch;scope={...value};const s=scope;current=null;screen='home';selectedStyle=null;root.replaceChildren(el('p',msg("ui.loading_specialist_tools")));
    if(!s.project){
      const identity=session().actor,csrf=session().csrf;
      if(!identity){root.replaceChildren(el('h1',msg("ui.standalone_screenplay_and_analysis_tools")),el('p','请先登录后打开独立工具工作区。'));return;}
      const sameSession=()=>alive(n,s)&&session().actor===identity&&session().csrf===csrf;
      const enter=async()=>{
        if(!sameSession())return;
        root.replaceChildren(el('p','正在打开独立工具工作区…'));
        const key=JSON.stringify([identity,csrf]);let request=workspaceRequests.get(key);
        if(!request){request=ctx.api('/api/v1/text-tools/workspace',{method:'POST',headers:{'X-CSRF-Token':csrf}});workspaceRequests.set(key,request);request.finally(()=>{if(workspaceRequests.get(key)===request)workspaceRequests.delete(key);}).catch(()=>{});}
        try{const result=await request;if(!sameSession()||workspaceActivation===n)return;workspaceActivation=n;await ctx.activateWorkspace(result.id);}
        catch(error){if(sameSession()){workspaceActivation=null;root.replaceChildren(el('h1',msg("ui.standalone_screenplay_and_analysis_tools")),el('p',error.message||String(error)),button('重试打开工作区',enter));}}
      };
      await enter();return;
    }
